def canon(cells, rot=True):
 pts=[(r,c) for r,c in cells]
 variants=[]
 for k in range(8 if rot else 1):
  tr=[]
  for r,c in pts:
   if k>=4: c=-c
   for _ in range(k%4): r,c=c,-r
   tr.append((r,c))
  mr=min(r for r,c in tr); mc=min(c for r,c in tr)
  variants.append(tuple(sorted((r-mr,c-mc) for r,c in tr)))
 return min(variants)
